  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../generated/client\"\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"ASSESSMENT_DATABASE_URL\")\n}\n\nenum AssessmentType {\n  OCEAN\n  RIASEC\n  APTITUDE\n  EQ\n  LEARNING\n}\n\nmodel AssessmentTrait {\n  id             String         @id @default(uuid())\n  code           String // e.g., \"O\", \"R\", \"SAW\", \"VIS\", \"NA\", etc.\n  name           String // e.g., \"Openness\", \"Realistic\", \"Self-Awareness\", \"Visual ↔ Verbal\"\n  assessmentType AssessmentType\n\n  questions Question[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([code, assessmentType]) // Ensure uniqueness per type\n}\n\nmodel Question {\n  id               String                @id @default(uuid())\n  traitId          String\n  trait            AssessmentTrait       @relation(fields: [traitId], references: [id])\n  order            Int\n  reverse          Boolean               @default(false)\n  timeLimitSeconds Int? // ⏳ NEW: Only used for APTITUDE MCQs\n  translations     QuestionTranslation[]\n  options          QuestionOption[] // Used for APTITUDE MCQs (empty for Likert: OCEAN/RIASEC/EQ/LEARNING)\n  createdAt        DateTime              @default(now())\n  updatedAt        DateTime              @updatedAt\n}\n\nmodel QuestionTranslation {\n  id         String   @id @default(uuid())\n  questionId String\n  question   Question @relation(fields: [questionId], references: [id])\n  language   String // ISO code like \"en\", \"hi\", \"mr\", \"fr\", etc.\n  text       String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([questionId, language]) // prevent duplicate language for same question\n}\n\nmodel QuestionOption {\n  id           String              @id @default(uuid())\n  questionId   String\n  question     Question            @relation(fields: [questionId], references: [id])\n  order        Int\n  isCorrect    Boolean             @default(false) // Only one correct per question (for Aptitude)\n  translations OptionTranslation[]\n  createdAt    DateTime            @default(now())\n  updatedAt    DateTime            @updatedAt\n}\n\nmodel OptionTranslation {\n  id        String         @id @default(uuid())\n  optionId  String\n  option    QuestionOption @relation(fields: [optionId], references: [id])\n  language  String\n  text      String\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  @@unique([optionId, language])\n}\n\nmodel AssessmentScore {\n  id                  String         @id @default(uuid())\n  userId              String         @db.Uuid\n  assessmentType      AssessmentType\n  traitOrCategoryCode String // e.g., 'O', 'C', 'R', 'I', 'Q', etc.\n  score               Int\n  createdAt           DateTime       @default(now())\n\n  @@index([userId, assessmentType, traitOrCategoryCode])\n}\n\nmodel UserAssessmentProgress {\n  id           String          @id @default(uuid())\n  userId       String          @db.Uuid\n  currentStage AssessmentType? // null means all completed\n  startedAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n\n  @@unique([userId])\n}\n\nmodel UserAssessmentPreference {\n  id                String   @id @default(uuid())\n  userId            String   @db.Uuid\n  preferredLanguage String\n  economicStatus    String\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@unique([userId]) // ensure one preference per user\n}\n",
